    op_reprs = {
        '+': ' + ', '-': ' - ', '*': ' * ', '/': ' / ',
        '#': ' // ', '%': ' % ', ':': ' ** ',
        '&': ' & ', '|': ' | ', '^': ' ^ ',
    }
    unary_ops = {'~': '~', '_': '-'}

    PREC = {
        ':': 8,
        '~': 7, '_': 7,
        '*': 6, '/': 6, '#': 6, '%': 6,
        '+': 5, '-': 5,
        '&': 4,
        '^': 3,
        '|': 2,
    }

    def needs_parens(op, child_op):
        if child_op not in PREC:
            return False
        if op not in PREC:
            return False
        return PREC[child_op] < PREC[op]

    result = root_str
    i = 0
    while i < len(path):
        op = path[i]
        arg = path[i + 1]
        i += 2

        if op == '.':
            result = result + '.' + arg
        elif op == '[':
            if isinstance(arg, slice):
                result = result + '[' + _format_slice(arg) + ']'
            elif isinstance(arg, tuple) and all(isinstance(x, slice) for x in arg):
                result = result + '[' + ', '.join(_format_slice(x) for x in arg) + ']'
            else:
                result = result + '[' + bbrepr(arg) + ']'
        elif op == 'P':
            result = result + '[' + bbrepr(arg) + ']'
        elif op == '(':
            args, kwargs = arg
            parts = [bbrepr(a) for a in args]
            parts += [f'{k}={bbrepr(v)}' for k, v in kwargs.items()]
            result = result + '(' + ', '.join(parts) + ')'
        elif op == 'x':
            result = result + '.__star__()'
        elif op == 'X':
            result = result + '.__starstar__()'
        elif op in op_reprs:
            sym = op_reprs[op]
            if isinstance(arg, TType):
                arg_ops = arg.__ops__
                arg_str = _format_t(arg_ops[1:], arg_ops[0])
                child_ops = arg_ops[1::2]
