def from_text(cls, text):
    def create():
        segs = text.split('.')
        if PATH_STAR:
            segs = [
                _T_STAR if seg == '*' else
                _T_STARSTAR if seg == '**' else seg
                for seg in segs]
        elif not cls._STAR_WARNED:
